// How the wave changes along its crest. The same functions exist in GLSL
// (see waveGLSL) and in JS so the surfer can ride exactly what the GPU draws.

export const WAVE = {
  scale: 3.2, // metres per profile unit
  speed: 3.6, // m/s the pattern slides past the surfer (peel speed)
  xMin: -340,
  xMax: 130,
  qMax: 230, // world half-extent of the wave mesh across the crest
};

const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const smooth = (a, b, x) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};
const mix = (a, b, t) => a + (b - a) * t;

// c: 0 = mellow shoulder, 1 = full barrel. h: size multiplier.
export function sliceState(x, t, out = { c: 0, h: 1 }) {
  const xp = x + t * WAVE.speed;
  let c = mix(1.0, 0.56, smooth(-45, 10, x));
  c = mix(c, 0.0, smooth(10, 95, x));
  c += 0.09 * Math.sin(xp / 11.0) + 0.06 * Math.sin(xp / 4.7 + 1.9) + 0.05 * Math.sin(xp / 27.0 + 0.7);
  c = clamp(c, 0, 1);
  let h = mix(1.0, 0.86, smooth(-30, 40, x));
  h *= 1.0 + 0.07 * Math.sin(xp / 19.0 + 2.3) + 0.04 * Math.sin(xp / 7.3);
  h *= smooth(-340, -250, x) * (1 - smooth(60, 125, x));
  out.c = c;
  out.h = h;
  return out;
}

export const waveGLSL = /* glsl */ `
#define WAVE_SPEED ${WAVE.speed.toFixed(3)}
float sm01(float a, float b, float x) { float t = clamp((x - a) / (b - a), 0.0, 1.0); return t * t * (3.0 - 2.0 * t); }
void sliceState(float x, float t, out float c, out float h) {
  float xp = x + t * WAVE_SPEED;
  c = mix(1.0, 0.56, sm01(-45.0, 10.0, x));
  c = mix(c, 0.0, sm01(10.0, 95.0, x));
  c += 0.09 * sin(xp / 11.0) + 0.06 * sin(xp / 4.7 + 1.9) + 0.05 * sin(xp / 27.0 + 0.7);
  c = clamp(c, 0.0, 1.0);
  h = mix(1.0, 0.86, sm01(-30.0, 40.0, x));
  h *= 1.0 + 0.07 * sin(xp / 19.0 + 2.3) + 0.04 * sin(xp / 7.3);
  h *= sm01(-340.0, -250.0, x) * (1.0 - sm01(60.0, 125.0, x));
}
`;

import * as THREE from "three";

// One shared sky function: used for the visible dome and, with the sun disc
// removed, for the image based lighting that the water, board and pelican share.

export const SUN_DIR = new THREE.Vector3(0.2, 0.5, 0.84).normalize();

export const PALETTE = {
  zenith: new THREE.Color("#2f67b8"),
  mid: new THREE.Color("#7fc0e6"),
  horizon: new THREE.Color("#ffe0b4"),
  sunTint: new THREE.Color("#ffb55c"),
  sunColor: new THREE.Color("#fff1d2"),
  ground: new THREE.Color("#2a8da0"),
};

const skyFrag = /* glsl */ `
uniform vec3 uSunDir;
uniform vec3 uZenith;
uniform vec3 uMid;
uniform vec3 uHorizon;
uniform vec3 uSunTint;
uniform vec3 uSunColor;
uniform vec3 uGround;
uniform float uTime;
uniform float uSunDisc;
varying vec3 vDir;

float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash21(i), hash21(i + vec2(1, 0)), f.x),
             mix(hash21(i + vec2(0, 1)), hash21(i + vec2(1, 1)), f.x), f.y);
}
float fbm(vec2 p) {
  float a = 0.5, s = 0.0;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = m * p; a *= 0.5; }
  return s;
}

vec3 skyColor(vec3 d) {
  float h = d.y;
  float hh = max(h, 0.0);
  float sd = max(dot(d, uSunDir), 0.0);

  vec3 col = mix(uHorizon, uMid, pow(smoothstep(0.0, 0.42, hh), 0.55));
  col = mix(col, uZenith, smoothstep(0.22, 0.95, hh));

  // warm glow around the sun, stronger low on the horizon
  float lowGlow = exp(-hh * 6.0);
  col += uSunTint * (pow(sd, 3.0) * 0.28 * lowGlow + pow(sd, 10.0) * 0.38 + pow(sd, 90.0) * 0.55);

  // clouds
  if (h > 0.0) {
    vec2 p = d.xz / (h * 0.85 + 0.16);
    vec2 drift = vec2(uTime * 0.012, uTime * 0.004);
    float n = fbm(p * 0.42 + drift);
    float cover = smoothstep(0.50, 0.82, n);
    float n2 = fbm(p * 0.42 + drift + normalize(uSunDir.xz + 1e-4) * 0.06);
    float lit = clamp((n - n2) * 5.0 + 0.55, 0.0, 1.0);
    float fadeH = smoothstep(0.0, 0.10, h);
    vec3 shade = mix(vec3(0.46, 0.56, 0.74), uHorizon * 0.9, 0.35);
    vec3 bright = mix(vec3(1.0, 0.97, 0.92), uSunTint * 1.5, pow(sd, 4.0) * 0.6);
    vec3 cc = mix(shade, bright, lit);
    // thin high wisps
    float wisp = smoothstep(0.55, 0.9, fbm(vec2(p.x * 0.18, p.y * 0.9) + drift * 0.5 + 7.0)) * 0.35 * smoothstep(0.05, 0.4, h);
    col = mix(col, cc, clamp(cover * fadeH * 0.92 + wisp * fadeH, 0.0, 1.0));
  }

  // below the horizon: the sea's own colour so reflections stay coherent
  col = mix(col, uGround * (0.55 + 0.45 * smoothstep(-0.9, 0.0, h)), smoothstep(0.0, -0.04, h));

  // sun disc
  col += uSunColor * smoothstep(0.99935, 0.99975, sd) * 18.0 * uSunDisc;
  return col;
}

void main() {
  gl_FragColor = vec4(skyColor(normalize(vDir)), 1.0);
}
`;

const skyVert = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = position;
  vec4 p = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  gl_Position = p.xyww;
}
`;

function makeSkyMaterial(disc) {
  return new THREE.ShaderMaterial({
    uniforms: {
      uSunDir: { value: SUN_DIR },
      uZenith: { value: PALETTE.zenith },
      uMid: { value: PALETTE.mid },
      uHorizon: { value: PALETTE.horizon },
      uSunTint: { value: PALETTE.sunTint },
      uSunColor: { value: PALETTE.sunColor },
      uGround: { value: PALETTE.ground },
      uTime: { value: 0 },
      uSunDisc: { value: disc },
    },
    vertexShader: skyVert,
    fragmentShader: skyFrag,
    side: THREE.BackSide,
    depthWrite: false,
    depthTest: false,
  });
}

export function createSky(renderer) {
  const geo = new THREE.SphereGeometry(1000, 48, 24);
  const mesh = new THREE.Mesh(geo, makeSkyMaterial(1));
  mesh.frustumCulled = false;
  mesh.renderOrder = -100;

  // environment (no sun disc: the directional light supplies the sun itself)
  const envScene = new THREE.Scene();
  const envMesh = new THREE.Mesh(geo, makeSkyMaterial(0));
  envMesh.frustumCulled = false;
  envScene.add(envMesh);
  const pmrem = new THREE.PMREMGenerator(renderer);
  const envRT = pmrem.fromScene(envScene, 0, 1, 3000);
  pmrem.dispose();

  return {
    mesh,
    envMap: envRT.texture,
    update(camera, t) {
      mesh.position.copy(camera.position);
      mesh.material.uniforms.uTime.value = t;
    },
  };
}

import * as THREE from "three";
import { NS, buildKeyframes, packKeyframes } from "./profile.js";
import { WAVE, waveGLSL } from "./wavefield.js";
import { SUN_DIR, PALETTE } from "./sky.js";

export const keyframes = buildKeyframes();

const vertexPars = /* glsl */ `
uniform sampler2D uProf0;
uniform sampler2D uProf1;
uniform float uTime;
uniform float uWScale;
uniform float uQMax;
varying vec3 vWPos;
varying vec3 vWN;
varying vec3 vWT;
varying vec3 vWB;
varying vec2 vPat;
varying vec4 vAttr;
${waveGLSL}
#define NS ${NS}

vec4 profFetch(sampler2D tex, float c, int idx) {
  float row = clamp(c, 0.0, 1.0) * 2.0;
  float r0 = min(floor(row), 1.0);
  float f = row - r0;
  vec4 a = texelFetch(tex, ivec2(idx, int(r0)), 0);
  vec4 b = texelFetch(tex, ivec2(idx, int(r0) + 1), 0);
  return mix(a, b, f);
}
vec3 slicePos(float x, int idx) {
  float c, h;
  sliceState(x, uTime, c, h);
  vec4 p = profFetch(uProf0, c, idx);
  float q = clamp(p.x * h * uWScale, -uQMax, uQMax);
  return vec3(x, p.y * h * uWScale, -q);
}
`;

const vertexNormal = /* glsl */ `
#ifdef OCEAN
  vec3 wpos = position;
  vec3 wN = vec3(0.0, 1.0, 0.0);
  vec3 wT = vec3(1.0, 0.0, 0.0);
  vec3 wB = vec3(0.0, 0.0, -1.0);
  vPat = vec2(position.x, -position.z);
  vAttr = vec4(1.0, 0.0, 0.0, 4.0);
#else
  float gx = position.x;
  int gi = int(position.y + 0.5);
  float sc, sh;
  sliceState(gx, uTime, sc, sh);
  vec3 wpos = slicePos(gx, gi);
  vec3 pX1 = slicePos(gx + 0.35, gi);
  vec3 pX0 = slicePos(gx - 0.35, gi);
  vec3 pS1 = slicePos(gx, min(gi + 1, NS - 1));
  vec3 pS0 = slicePos(gx, max(gi - 1, 0));
  vec3 dX = pX1 - pX0;
  vec3 dS = pS1 - pS0;
  vec3 wN = cross(dX, dS);
  float nl = length(wN);
  wN = nl > 1e-6 ? wN / nl : vec3(0.0, 1.0, 0.0);
  vec3 wT = normalize(dX + vec3(1e-5, 0.0, 0.0));
  vec3 wB = normalize(cross(wN, wT));
  vec4 pr0 = profFetch(uProf0, sc, gi);
  vec4 pr1 = profFetch(uProf1, sc, gi);
  vPat = vec2(gx, pr0.z * sh * uWScale);
  vAttr = vec4(pr0.w, pr1.x, pr1.y, pr1.z);
#endif
  vWPos = wpos;
  vWN = wN;
  vWT = wT;
  vWB = wB;
  vec3 objectNormal = wN;
`;

const fragPars = /* glsl */ `
uniform float uTime;
uniform vec3 uDeep;
uniform vec3 uShallow;
uniform vec3 uGlow;
uniform vec3 uFoamCol;
uniform vec3 uHorizon;
uniform vec3 uSunTint;
uniform vec3 uSunDirW;
uniform float uSpeed;
varying vec3 vWPos;
varying vec3 vWN;
varying vec3 vWT;
varying vec3 vWB;
varying vec2 vPat;
varying vec4 vAttr;

float h21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
// value noise with analytic derivatives
vec3 noised(vec2 x) {
  vec2 i = floor(x);
  vec2 f = fract(x);
  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  vec2 du = 30.0 * f * f * (f * (f - 2.0) + 1.0);
  float a = h21(i);
  float b = h21(i + vec2(1.0, 0.0));
  float c = h21(i + vec2(0.0, 1.0));
  float d = h21(i + vec2(1.0, 1.0));
  float k1 = b - a, k2 = c - a, k4 = a - b - c + d;
  return vec3(a + k1 * u.x + k2 * u.y + k4 * u.x * u.y, du * (vec2(k1, k2) + k4 * u.yx));
}
float fbm4(vec2 p) {
  float a = 0.5, s = 0.0;
  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);
  for (int i = 0; i < 4; i++) { s += a * noised(p).x; p = m * p; a *= 0.5; }
  return s;
}
// gradient of the ripple height field
vec2 rippleGrad(vec2 p, float px, float amp) {
  vec2 g = vec2(0.0);
  float a = amp;
  float f = 1.0;
  mat2 R = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 5; i++) {
    vec3 n = noised(p * f);
    float fade = 1.0 - smoothstep(0.25, 0.7, f * px);
    g += a * (n.yz - 0.5 * 0.0) * f * fade;
    p = R * p + 3.7;
    f *= 2.15;
    a *= 0.52;
  }
  return g;
}
vec3 hazeColor(vec3 d) {
  float sd = max(dot(d, uSunDirW), 0.0);
  return uHorizon + uSunTint * (pow(sd, 3.0) * 0.28 + pow(sd, 10.0) * 0.38 + pow(sd, 90.0) * 0.55);
}
`;

const fragSurface = /* glsl */ `
  vec3 toEye = cameraPosition - vWPos;
  float dist = length(toEye);
  vec3 V = -toEye / dist;
  vec3 Nw = normalize(vWN);
  vec3 Tw = normalize(vWT);
  vec3 Bw = normalize(vWB);

  float thickness = vAttr.x;
  float aoIn = vAttr.y;
  float foamMask = vAttr.z;

  // pattern coordinates; the sea slides under the pattern and climbs the face
  float xp = vPat.x + uTime * uSpeed;
  float arc = vPat.y;
  vec2 pc = vec2(xp, arc + uTime * 1.1);
  float px = length(fwidth(pc));

  float distFade = 1.0 / (1.0 + dist * 0.012);
  vec2 g = rippleGrad(pc * 0.9, px * 0.9, 0.055) * distFade;
  vec2 g2 = rippleGrad(vec2(xp * 0.35 + 11.0, (arc + uTime * 0.5) * 1.3), px * 0.4, 0.16) * distFade;
  vec2 gg = g + g2;
  Nw = normalize(Nw - (gg.x * Tw + gg.y * Bw));
  normal = normalize((viewMatrix * vec4(Nw, 0.0)).xyz);

  // ---- body colour (what the eye sees through the water)
  float thin = 1.0 - thickness;
  vec3 body = mix(uDeep, uShallow, 0.12 + 0.88 * pow(thin, 1.4));
  body *= 1.0 - 0.6 * aoIn * (1.0 - 0.0);

  // ---- foam
  float fn = fbm4(pc * vec2(1.6, 1.3) + vec2(0.0, 4.0));
  float fs = fbm4(vec2(xp * 3.2, arc * 0.7 + uTime * 0.6) + 9.0);
  float nz = 0.55 * fn + 0.45 * fs;
  float thr = 1.0 - foamMask * 1.25;
  float foam = smoothstep(thr, thr + 0.28, nz + foamMask * 0.18);
  // scattered flecks over the open sea
  float fleck = smoothstep(0.80, 0.92, fbm4(vec2(xp, arc) * 0.35 + 3.0)) * 0.55;
  foam = max(foam, fleck * (1.0 - foamMask) * 0.6);
  foam *= 1.0 - smoothstep(250.0, 700.0, dist);

  diffuseColor.rgb = mix(body, uFoamCol, foam);
  roughnessFactor = mix(0.05 + smoothstep(30.0, 500.0, dist) * 0.25, 0.85, foam);

  // ---- light shining through the thin parts of the wave
  float sunBack = pow(clamp(dot(V, uSunDirW), 0.0, 1.0), 2.2);
  float glowAmt = pow(thin, 1.5) * (0.3 + 1.6 * sunBack) + 0.04;
  vec3 waterGlow = uGlow * glowAmt * (1.0 - foam) * (1.0 - 0.5 * aoIn);
`;

const fragFog = /* glsl */ `
  {
    float fogAmt = 1.0 - exp(-pow(dist * 0.0042, 1.25));
    vec3 fogCol = hazeColor(normalize(vec3(V.x, 0.0, V.z)));
    gl_FragColor.rgb = mix(gl_FragColor.rgb, fogCol, fogAmt);
  }
`;

export function createWaterMaterials(envMap) {
  const t0 = new THREE.DataTexture(null, 1, 1);
  const [d0, d1] = packKeyframes(keyframes);
  const mk = (data) => {
    const t = new THREE.DataTexture(data, NS, keyframes.length, THREE.RGBAFormat, THREE.FloatType);
    t.minFilter = t.magFilter = THREE.NearestFilter;
    t.needsUpdate = true;
    return t;
  };
  t0.dispose();
  const shared = {
    uTime: { value: 0 },
    uProf0: { value: mk(d0) },
    uProf1: { value: mk(d1) },
    uWScale: { value: WAVE.scale },
    uQMax: { value: WAVE.qMax },
    uSpeed: { value: WAVE.speed },
    uDeep: { value: new THREE.Color("#04283a") },
    uShallow: { value: new THREE.Color("#0f9aa0") },
    uGlow: { value: new THREE.Color("#2fe0b4").multiplyScalar(0.9) },
    uFoamCol: { value: new THREE.Color("#f2fbff") },
    uHorizon: { value: PALETTE.horizon },
    uSunTint: { value: PALETTE.sunTint },
    uSunDirW: { value: SUN_DIR },
  };

  const make = (ocean) => {
    const m = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.06,
      metalness: 0,
      envMap,
      envMapIntensity: 1.0,
    });
    m.defines = ocean ? { OCEAN: "" } : {};
    m.onBeforeCompile = (shader) => {
      Object.assign(shader.uniforms, shared);
      shader.vertexShader = shader.vertexShader
        .replace("#include <common>", "#include <common>\n" + vertexPars)
        .replace("#include <beginnormal_vertex>", vertexNormal)
        .replace("#include <begin_vertex>", "vec3 transformed = wpos;");
      shader.fragmentShader = shader.fragmentShader
        .replace("#include <common>", "#include <common>\n" + fragPars)
        .replace("#include <normal_fragment_maps>", fragSurface)
        .replace("#include <emissivemap_fragment>", "#include <emissivemap_fragment>\n totalEmissiveRadiance += waterGlow;")
        .replace("#include <fog_fragment>", fragFog);
    };
    m.customProgramCacheKey = () => (ocean ? "ocean" : "wave");
    return m;
  };

  return { wave: make(false), ocean: make(true), uniforms: shared };
}

// Wave mesh: a grid over (slice x, profile index) evaluated entirely in the vertex shader.
export function createWaveGeometry() {
  const xs = [];
  const sideL = 170;
  const sideR = 90;
  const a = 3.5;
  const ex = (s) => (Math.exp(a * s) - 1) / (Math.exp(a) - 1);
  for (let i = sideL; i >= 1; i--) xs.push(-ex(i / sideL) * -WAVE.xMin * -1 * -1);
  // build ascending list of x
  const list = [];
  for (let i = sideL; i >= 1; i--) list.push(WAVE.xMin * ex(i / sideL));
  list.push(0);
  for (let i = 1; i <= sideR; i++) list.push(WAVE.xMax * ex(i / sideR));
  const NX = list.length;
  const pos = new Float32Array(NX * NS * 3);
  for (let i = 0; i < NX; i++) {
    for (let j = 0; j < NS; j++) {
      const o = (i * NS + j) * 3;
      pos[o] = list[i];
      pos[o + 1] = j;
      pos[o + 2] = 0;
    }
  }
  const idx = new Uint32Array((NX - 1) * (NS - 1) * 6);
  let k = 0;
  for (let i = 0; i < NX - 1; i++) {
    for (let j = 0; j < NS - 1; j++) {
      const a0 = i * NS + j;
      const b0 = (i + 1) * NS + j;
      const c0 = i * NS + j + 1;
      const d0 = (i + 1) * NS + j + 1;
      idx[k++] = a0;
      idx[k++] = b0;
      idx[k++] = c0;
      idx[k++] = b0;
      idx[k++] = d0;
      idx[k++] = c0;
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
  g.setIndex(new THREE.BufferAttribute(idx, 1));
  return g;
}

// Flat sea around the wave mesh (with a hole where the wave mesh lives).
export function createOceanGeometry() {
  const R = 9000;
  const x0 = WAVE.xMin;
  const x1 = WAVE.xMax;
  const z0 = -WAVE.qMax;
  const z1 = WAVE.qMax;
  const quads = [
    [-R, -R, x0, R], // left strip (full height)
    [x1, -R, R, R], // right strip
    [x0, -R, x1, z0], // near strip
    [x0, z1, x1, R], // far strip
  ];
  const pos = [];
  for (const [ax, az, bx, bz] of quads) {
    pos.push(ax, 0, az, ax, 0, bz, bx, 0, az);
    pos.push(bx, 0, az, ax, 0, bz, bx, 0, bz);
  }
  // winding: make normals face +Y
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
  return g;
}

