import * as THREE from "three";
import { EffectComposer } from "three/addons/postprocessing/EffectComposer.js";
import { RenderPass } from "three/addons/postprocessing/RenderPass.js";
import { UnrealBloomPass } from "three/addons/postprocessing/UnrealBloomPass.js";
import { OutputPass } from "three/addons/postprocessing/OutputPass.js";
import { createSky, SUN_DIR } from "./src/sky.js";
import { createWaterMaterials, createWaveGeometry, createOceanGeometry } from "./src/water.js";

const params = new URLSearchParams(location.search);
const fixedT = params.has("t") ? parseFloat(params.get("t")) : null;

const renderer = new THREE.WebGLRenderer({ antialias: false, powerPreference: "high-performance" });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(42, window.innerWidth / window.innerHeight, 0.1, 6000);

const sky = createSky(renderer);
scene.add(sky.mesh);
scene.environment = sky.envMap;

const sun = new THREE.DirectionalLight(0xfff0d8, 3.2);
sun.position.copy(SUN_DIR).multiplyScalar(60);
scene.add(sun, sun.target);

const water = createWaterMaterials(sky.envMap);
const waveMesh = new THREE.Mesh(createWaveGeometry(), water.wave);
waveMesh.frustumCulled = false;
waveMesh.receiveShadow = true;
scene.add(waveMesh);
const oceanMesh = new THREE.Mesh(createOceanGeometry(), water.ocean);
oceanMesh.frustumCulled = false;
scene.add(oceanMesh);

// ---- post
const composer = new EffectComposer(
  renderer,
  new THREE.WebGLRenderTarget(1, 1, { type: THREE.HalfFloatType, samples: 4 }),
);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 0.35, 0.8, 0.9);
composer.addPass(bloom);
composer.addPass(new OutputPass());

function resize() {
  const w = window.innerWidth;
  const h = window.innerHeight;
  renderer.setSize(w, h);
  composer.setSize(w, h);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
}
window.addEventListener("resize", resize);
resize();

const camOverride = params.get("cam");

function frame(t) {
  water.uniforms.uTime.value = t;
  sky.update(camera, t);
  if (camOverride) {
    const v = camOverride.split(",").map(Number);
    camera.position.set(v[0], v[1], v[2]);
    camera.lookAt(v[3], v[4], v[5]);
    if (v[6]) {
      camera.fov = v[6];
      camera.updateProjectionMatrix();
    }
  } else {
    camera.position.set(14, 2.2, -10);
    camera.lookAt(-4, 1.6, 1);
  }
  composer.render();
}

if (fixedT !== null) {
  frame(fixedT);
  frame(fixedT);
  window.__ready = true;
} else {
  const clock = new THREE.Clock();
  const loop = () => {
    frame(clock.getElapsedTime());
    requestAnimationFrame(loop);
  };
  loop();
}

