import * as THREE from "three";
import { clamp, lerp, smoothstep } from "./geo.js";

// A slow, drifting camera that keeps the pelican framed against the wave.
export function createRig(camera, surfer) {
  const target = new THREE.Vector3();
  const look = new THREE.Vector3();
  const pos = new THREE.Vector3();
  const desired = new THREE.Vector3();
  const vel = new THREE.Vector3();
  let init = false;

  const noise = (t, s) => Math.sin(t * 1.7 * s + 1.3) * 0.5 + Math.sin(t * 2.9 * s + 4.1) * 0.3 + Math.sin(t * 4.3 * s) * 0.2;

  function shot(t) {
    // azimuth around the surfer in the xz plane: 0 = ahead of the pelican, -90 = out on the open water
    const phi = THREE.MathUtils.degToRad(-62 + 38 * Math.sin(t * 0.075 + 0.6) + 10 * Math.sin(t * 0.19 + 2.0));
    const R = 6.4 + 1.8 * Math.sin(t * 0.11 + 1.9) + 0.8 * Math.sin(t * 0.27);
    const h = 1.15 + 0.55 * Math.sin(t * 0.09 + 0.2) + 0.2 * Math.sin(t * 0.31 + 1.0);
    const fov = 38 + 3 * Math.sin(t * 0.07 + 1.0);
    return { phi, R, h, fov };
  }

  function update(t, dt) {
    const sp = surfer.state.pos;
    target.copy(sp);
    const s = shot(t);
    desired.set(sp.x + s.R * Math.cos(s.phi), sp.y + s.h, sp.z + s.R * Math.sin(s.phi));
    // stay on the open-water side of the wave
    desired.z = Math.min(desired.z, sp.z - 4.2);
    desired.y = Math.max(desired.y, 0.9);
    if (!init) {
      pos.copy(desired);
      look.copy(target);
      init = true;
    } else {
      const k = 1 - Math.exp(-dt * 2.2);
      pos.lerp(desired, k);
      look.lerp(target, 1 - Math.exp(-dt * 3.0));
    }
    camera.position.copy(pos);
    // gentle handheld sway
    camera.position.x += 0.04 * noise(t, 0.9);
    camera.position.y += 0.05 * noise(t + 5, 1.1);
    camera.position.z += 0.04 * noise(t + 9, 0.8);
    const aim = look.clone();
    aim.y += 0.95;
    camera.lookAt(aim);
    camera.rotateZ(0.012 * noise(t + 3, 0.7));
    if (Math.abs(camera.fov - s.fov) > 1e-3) {
      camera.fov = s.fov;
      camera.updateProjectionMatrix();
    }
  }
  return { update, shot };
}
