import * as THREE from "three";
import { WAVE } from "./wavefield.js";

// Records where the board has been, in the frame of the sea, so the water shader can paint a wake.
export function createTrail(uniforms) {
  const N = 48;
  const arr = uniforms.uTrail.value;
  const bounds = uniforms.uTrailBounds.value;
  let head = 0;
  let acc = 0;
  const step = 1 / 11.5;

  function push(t, xw, arc, strength) {
    const s = arr[head];
    s.set(xw + t * WAVE.speed, arc + t * 1.1, t, strength);
    head = (head + 1) % N;
  }

  function update(t, dt, st) {
    acc += dt;
    while (acc >= step) {
      acc -= step;
      push(t, st.tailX, st.tailArc, 0.55 + 0.45 * st.energy);
    }
    let x0 = 1e9;
    let x1 = -1e9;
    let p0 = 1e9;
    let p1 = -1e9;
    for (const s of arr) {
      if (s.w <= 0 || t - s.z > 4.3) continue;
      x0 = Math.min(x0, s.x);
      x1 = Math.max(x1, s.x);
      p0 = Math.min(p0, s.y);
      p1 = Math.max(p1, s.y);
    }
    bounds.set(x0 - 3.5, x1 + 3.5, p0 - 3.5, p1 + 3.5);
  }
  return { update };
}
