  for (let t = -4; t < 0; t += 1 / 30) simulate(t, 1 / 30);

  // keep the frame rate up on slower machines by trading resolution
  let last = performance.now();
  let avg = 16;
  let frames = 0;
  let clockT = 0;
  const loop = (now) => {
    const ms = Math.min(now - last, 100);
    last = now;
    avg += (ms - avg) * 0.08;
    clockT += Math.min(ms / 1000, 1 / 20);
    simulate(clockT, Math.min(ms / 1000, 1 / 20));
    render();
    if (++frames % 40 === 0) {
      let next = pixelRatio;
      if (avg > 22 && pixelRatio > 0.55) next = Math.max(0.55, pixelRatio * 0.88);
      else if (avg < 13 && pixelRatio < maxPixelRatio) next = Math.min(maxPixelRatio, pixelRatio * 1.1);
      if (Math.abs(next - pixelRatio) > 0.01) {
        pixelRatio = next;
        resize();
      }
    }
    requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
}

