233	  float distFade = 1.0 / (1.0 + dist * 0.01);
234	  // gentle domain warp so the wave trains do not look like a lattice
235	  vec2 wp = pc + 0.55 * vec2(sin(pc.y * 0.31 + pc.x * 0.17), sin(pc.x * 0.27 - pc.y * 0.23 + 1.3));
236	  #ifdef NO_WAVES
237	  vec2 gg = vec2(0.0);
238	  #else
239	  vec2 gg = waveGrad(wp, px, uTime) * uRipple * distFade;
240	  #endif
241	  Nw = normalize(Nw - (gg.x * Tw + gg.y * Bw));
242	  normal = normalize((viewMatrix * vec4(Nw, 0.0)).xyz);
243	
244	  // ---- foam (the expensive noise only runs where there is foam to draw)
245	  #ifdef NO_TRAIL
246	  float td = 0.0;
247	  #else
248	  float td = trailFoam(vec2(pc.x, pc.y));
249	  #endif
250	  float foam = 0.0;
251	  float lace = 1.0;
252	  #ifdef NO_FOAM
253	  if (false) {
254	  #else
255	  if (foamMask > 0.02 || td > 0.01) {
256	  #endif
257	    float fn = fbm3(pc * vec2(1.3, 1.1) + vec2(0.0, 4.0));
258	    float fs = fbm3(vec2(xp * 2.4, arc * 0.9 + uTime * 0.6) + 9.0);
259	    float nz = 0.6 * fn + 0.4 * fs;
260	    float thr = 1.0 - foamMask * 1.3;
261	    foam = smoothstep(thr, thr + 0.3, nz + foamMask * 0.2);
262	    if (td > 0.01) {
263	      float streak = fbm3(vec2(xp * 1.1, arc * 6.5) + 3.0);
264	      foam = max(foam, smoothstep(0.1, 0.5, td * (0.3 + 1.2 * streak)));
265	    }
266	    // bubbly lace, only worth the cost close to the camera
267	    float tone = mix(0.7, 1.0, smoothstep(0.25, 0.75, fn));
268	    lace = tone;
269	    if (dist < 70.0) {
270	      float bub = worley(pc * vec2(5.5, 4.5) + vec2(2.0, 9.0));
271	      lace *= mix(0.8, 1.0, smoothstep(0.08, 0.4, bub));
272	    }
273	  }
274	  float fleck = smoothstep(0.8, 0.96, noised(pc * 0.45 + 3.0).x) * 0.5;
275	  foam = max(foam, fleck * (1.0 - foamMask) * 0.5);
276	  foam *= 1.0 - smoothstep(250.0, 800.0, dist);
277	
278	  // ---- body colour: sunlight scattered inside the water, mostly independent of the surface normal
279	  float thin = clamp(1.0 - thickness, 0.0, 1.0);
280	  vec3 vol = mix(uDeep, uShallow, 0.1 + 0.9 * pow(thin, 1.25));
281	  float wrap = clamp(dot(Nw, uSunDirW) * 0.5 + 0.5, 0.0, 1.0);
282	  vec3 scatter = vol * (0.5 + 0.9 * wrap);
283	  float sunBack = pow(clamp(dot(V, uSunDirW), 0.0, 1.0), 2.0);
284	  scatter += uGlow * pow(thin, 1.4) * (0.22 + 1.5 * sunBack);
285	  scatter *= 1.0 - 0.6 * aoIn;
286	
287	  // churned water: bright where aerated, bluish in the hollows between the bubbles
288	  diffuseColor.rgb = mix(vec3(0.62, 0.8, 0.88), uFoamCol, lace) * foam;
289	  roughnessFactor = mix(0.04 + smoothstep(30.0, 500.0, dist) * 0.25, 0.85, foam);
290	  vec3 waterGlow = scatter * (1.0 - foam);
291	  #ifdef DEBUGATTR
292	  diffuseColor.rgb = vec3(0.0); waterGlow = vec3(thickness, aoIn, foamMask);
293	  #endif
294	`;
295	
296	const fragFog = /* glsl */ `
297	  {
298	    float fogAmt = 1.0 - exp(-pow(dist * 0.0042, 1.25));
299	    vec3 fogCol = hazeColor(normalize(vec3(V.x, 0.0, V.z)));
300	    gl_FragColor.rgb = mix(gl_FragColor.rgb, fogCol, fogAmt);
301	    if (any(isnan(gl_FragColor.rgb)) || any(isinf(gl_FragColor.rgb))) gl_FragColor = vec4(fogCol, 1.0);
302	  }
303	`;
