305	export function createWaterMaterials(envMap) {
306	  const [d0, d1] = packKeyframes(keyframes);
307	  const mk = (data) => {
308	    const t = new THREE.DataTexture(data, NS, keyframes.length, THREE.RGBAFormat, THREE.FloatType);
309	    t.minFilter = t.magFilter = THREE.NearestFilter;
310	    t.needsUpdate = true;
311	    return t;
312	  };
313	  const shared = {
314	    uTime: { value: 0 },
315	    uProf0: { value: mk(d0) },
316	    uProf1: { value: mk(d1) },
317	    uWScale: { value: WAVE.scale },
318	    uQMax: { value: WAVE.qMax },
319	    uSpeed: { value: WAVE.speed },
320	    uRipple: { value: 1.0 },
321	    uClimb: { value: WAVE.climb },
322	    uTrail: { value: Array.from({ length: 48 }, () => new THREE.Vector4(0, 0, -1e5, 0)) },
323	    uTrailBounds: { value: new THREE.Vector4(1, -1, 1, -1) },
324	    uDeep: { value: new THREE.Color("#0a4d66") },
325	    uShallow: { value: new THREE.Color("#22b9aa") },
326	    uGlow: { value: new THREE.Color("#4eeabf").multiplyScalar(0.9) },
327	    uFoamCol: { value: new THREE.Color("#f2fbff") },
328	    uHorizon: { value: PALETTE.horizon },
329	    uHorizonCool: { value: PALETTE.horizonCool },
330	    uSunTint: { value: PALETTE.sunTint },
331	    uSunDirW: { value: SUN_DIR },
332	  };
333	
334	  const make = (ocean, depthOnly = false) => {
335	    const m = new THREE.MeshStandardMaterial({
336	      color: 0xffffff,
337	      roughness: 0.06,
338	      metalness: 0,
339	      envMap,
340	      envMapIntensity: 1.0,
341	    });
342	    m.defines = ocean ? { OCEAN: "" } : {};
343	    for (const k of (new URLSearchParams(location.search).get("wno") || "").split(",")) if (k) m.defines["NO_" + k.toUpperCase()] = "";
344	    if (new URLSearchParams(location.search).has("dbgattr")) m.defines.DEBUGATTR = "";
345	    if (depthOnly) {
346	      // depth pre-pass: same displacement, no shading, so the colour pass shades each pixel only once
347	      m.colorWrite = false;
348	      m.polygonOffset = true;
349	      m.polygonOffsetFactor = 1;
350	      m.polygonOffsetUnits = 1;
351	    } else if (!ocean) {
352	      m.depthFunc = THREE.LessEqualDepth;
353	    }
354	    m.onBeforeCompile = (shader) => {
355	      Object.assign(shader.uniforms, shared);
356	      shader.vertexShader = shader.vertexShader
357	        .replace("#include <common>", "#include <common>\n" + vertexPars)
358	        .replace("#include <beginnormal_vertex>", vertexNormal)
359	        .replace("#include <begin_vertex>", "vec3 transformed = wpos;");
360	      shader.fragmentShader = shader.fragmentShader
361	        .replace("#include <common>", "#include <common>\n" + fragPars)
362	        .replace("#include <normal_fragment_maps>", QUAL === 0 ? "vec3 waterGlow = vec3(0.1,0.4,0.5);" : fragSurface)
363	        .replace("#include <emissivemap_fragment>", "#include <emissivemap_fragment>\n totalEmissiveRadiance += waterGlow;")
364	        .replace("#include <fog_fragment>", fragFog);
365	      if (depthOnly) shader.fragmentShader = "void main() { gl_FragColor = vec4(0.0); }";
366	    };
367	    m.customProgramCacheKey = () => (depthOnly ? "wave-depth" : ocean ? "ocean" : "wave");
368	    return m;
369	  };
370	
371	  return { wave: make(false), waveDepth: make(false, true), ocean: make(true), uniforms: shared };
372	}
