374	// Wave mesh: a grid over (slice x, profile index) evaluated entirely in the vertex shader.
375	export function createWaveGeometry() {
376	  const sideL = 170;
377	  const sideR = 90;
378	  const a = 3.5;
379	  const ex = (s) => (Math.exp(a * s) - 1) / (Math.exp(a) - 1);
380	  const list = [];
381	  for (let i = sideL; i >= 1; i--) list.push(WAVE.xMin * ex(i / sideL));
382	  list.push(0);
383	  for (let i = 1; i <= sideR; i++) list.push(WAVE.xMax * ex(i / sideR));
384	  const NX = list.length;
385	  const pos = new Float32Array(NX * NS * 3);
386	  for (let i = 0; i < NX; i++) {
387	    for (let j = 0; j < NS; j++) {
388	      const o = (i * NS + j) * 3;
389	      pos[o] = list[i];
390	      pos[o + 1] = j;
391	      pos[o + 2] = 0;
392	    }
393	  }
394	  const idx = new Uint32Array((NX - 1) * (NS - 1) * 6);
395	  let k = 0;
396	  for (let i = 0; i < NX - 1; i++) {
397	    for (let j = 0; j < NS - 1; j++) {
398	      const a0 = i * NS + j;
399	      const b0 = (i + 1) * NS + j;
400	      const c0 = i * NS + j + 1;
401	      const d0 = (i + 1) * NS + j + 1;
402	      idx[k++] = a0;
403	      idx[k++] = b0;
404	      idx[k++] = c0;
405	      idx[k++] = b0;
406	      idx[k++] = d0;
407	      idx[k++] = c0;
408	    }
409	  }
410	  const g = new THREE.BufferGeometry();
411	  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
412	  g.setIndex(new THREE.BufferAttribute(idx, 1));
413	  return g;
414	}
415	
416	// Flat sea around the wave mesh (with a hole where the wave mesh lives).
417	export function createOceanGeometry() {
418	  const R = 9000;
419	  const x0 = WAVE.xMin;
420	  const x1 = WAVE.xMax;
421	  const z0 = -WAVE.qMax;
422	  const z1 = WAVE.qMax;
423	  const quads = [
424	    [-R, -R, x0, R], // left strip (full height)
425	    [x1, -R, R, R], // right strip
426	    [x0, -R, x1, z0], // near strip
427	    [x0, z1, x1, R], // far strip
428	  ];
429	  const pos = [];
430	  for (const [ax, az, bx, bz] of quads) {
431	    pos.push(ax, 0, az, ax, 0, bz, bx, 0, az);
432	    pos.push(bx, 0, az, ax, 0, bz, bx, 0, bz);
433	  }
434	  // winding: make normals face +Y
435	  const g = new THREE.BufferGeometry();
436	  g.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
437	  return g;
438	}
